ALTER TABLE public.mcp_audit_log ADD COLUMN IF NOT EXISTS affaire_id uuid;
ALTER TABLE public.mcp_audit_log ADD COLUMN IF NOT EXISTS etape_id uuid;
ALTER TABLE public.mcp_audit_log ADD COLUMN IF NOT EXISTS confirmation_id uuid;
ALTER TABLE public.mcp_audit_log ADD COLUMN IF NOT EXISTS diff jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.mcp_audit_log DROP CONSTRAINT mcp_audit_log_statut_check;
ALTER TABLE public.mcp_audit_log ADD CONSTRAINT mcp_audit_log_statut_check CHECK(statut IN ('ok','refuse','erreur','rate_limited','preview','executed','refused'));
CREATE TABLE public.mcp_write_confirmations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,client_id text NOT NULL,tool text NOT NULL,arguments_hash text NOT NULL,payload_hash text NOT NULL,affaire_id uuid,etape_id uuid,snapshot text,expires_at timestamptz NOT NULL DEFAULT now()+interval '10 minutes',executed_at timestamptz,result jsonb);
GRANT SELECT ON public.mcp_write_confirmations TO authenticated;
GRANT ALL ON public.mcp_write_confirmations TO service_role;
ALTER TABLE public.mcp_write_confirmations ENABLE ROW LEVEL SECURITY;
CREATE POLICY mcp_confirmation_owner ON public.mcp_write_confirmations FOR SELECT TO authenticated USING(user_id=auth.uid() AND client_id=auth.jwt()->>'client_id');
CREATE TABLE public.mcp_write_external_keys(tool text NOT NULL,key_hash text NOT NULL,affaire_id uuid NOT NULL,etape_id uuid,result jsonb NOT NULL,PRIMARY KEY(tool,key_hash));
GRANT SELECT ON public.mcp_write_external_keys TO authenticated;
GRANT ALL ON public.mcp_write_external_keys TO service_role;
ALTER TABLE public.mcp_write_external_keys ENABLE ROW LEVEL SECURITY;
CREATE POLICY mcp_external_read ON public.mcp_write_external_keys FOR SELECT TO authenticated USING(user_has_cap('api.mcp.write') AND (user_cap_scope('section.affaires')='all' OR user_has_affaire_access(affaire_id)));
CREATE OR REPLACE FUNCTION public.mcp_assert_write(_tool text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c text:=auth.jwt()->>'client_id'; cap text; BEGIN IF auth.uid() IS NULL OR c IS NULL OR NOT user_has_cap('api.mcp') OR NOT user_has_cap('api.mcp.write') OR NOT is_feature_flag_enabled('mcp_v1') OR NOT is_feature_flag_enabled('mcp_v2_write') OR NOT EXISTS(SELECT 1 FROM mcp_connections WHERE user_id=auth.uid() AND client_id=c AND revoked_at IS NULL) THEN RAISE EXCEPTION 'Écriture MCP refusée'; END IF; cap:=CASE WHEN _tool='creer_opportunite' THEN 'action.create_opportunite' WHEN _tool IN ('ajouter_action_opportunite','mettre_a_jour_opportunite') THEN 'action.edit_opportunite' WHEN _tool IN ('modifier_chantier','ajouter_note_chantier') THEN 'section.affaires' WHEN _tool IN ('creer_etape_logistique','modifier_etape_logistique','deplacer_etape_logistique','annuler_etape_logistique') THEN 'logistique.etape.edit' END; IF cap IS NULL OR NOT user_has_cap(cap) THEN RAISE EXCEPTION 'Outil ou droit métier refusé'; END IF; RETURN cap; END $$;
CREATE OR REPLACE FUNCTION public.mcp_safe_diff(_diff jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT COALESCE(jsonb_object_agg(key,CASE WHEN key IN ('date_debut','date_fin','date_montage','date_demontage','date_evenement_debut','date_evenement_fin','statut','statut_opportunite','type','ca_estime_ht','montage_nb_techniciens','montage_travail_nuit','montage_nb_semi','montage_nb_20m3') AND length(value::text)<200 THEN value ELSE jsonb_build_object('modifie',true) END),'{}'::jsonb) FROM jsonb_each(CASE WHEN jsonb_typeof(_diff)='object' THEN _diff ELSE '{}'::jsonb END) WHERE length(key)<64 $$;
CREATE OR REPLACE FUNCTION public.mcp_write_preview(_tool text,_arguments_hash text,_payload jsonb,_affaire_id uuid DEFAULT NULL,_etape_id uuid DEFAULT NULL,_snapshot text DEFAULT NULL,_diff jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; cap text; a public.affaires; BEGIN cap:=mcp_assert_write(_tool); IF _affaire_id IS NOT NULL THEN SELECT * INTO a FROM affaires WHERE id=_affaire_id AND archived_at IS NULL; IF NOT FOUND OR NOT (user_cap_scope(cap)='all' OR (user_cap_scope(cap)='own' AND a.charge_affaires_id=auth.uid()) OR user_has_affaire_access(_affaire_id)) THEN RAISE EXCEPTION 'Accès affaire refusé'; END IF; END IF; IF _etape_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM affaire_etapes_logistiques WHERE id=_etape_id AND affaire_id=_affaire_id) THEN RAISE EXCEPTION 'Étape incohérente'; END IF; INSERT INTO mcp_write_confirmations(user_id,client_id,tool,arguments_hash,payload_hash,affaire_id,etape_id,snapshot) VALUES(auth.uid(),auth.jwt()->>'client_id',_tool,_arguments_hash,encode(extensions.digest(_payload::text,'sha256'),'hex'),_affaire_id,_etape_id,_snapshot) RETURNING id INTO cid; INSERT INTO mcp_audit_log(user_id,client_id,tool,statut,confirmation_id,affaire_id,etape_id,diff) VALUES(auth.uid(),auth.jwt()->>'client_id',_tool,'preview',cid,_affaire_id,_etape_id,mcp_safe_diff(_diff)); RETURN jsonb_build_object('confirmation_id',cid,'expires_at',now()+interval '10 minutes'); END $$;
GRANT USAGE,CREATE ON SCHEMA public TO mcp_business_rls;
CREATE OR REPLACE FUNCTION public.mcp_dispatch_write(_tool text,_p jsonb,_affaire_id uuid,_etape_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; k text; patch jsonb; allowed text[]; a public.affaires; BEGIN PERFORM mcp_assert_write(_tool); IF _tool IN ('ajouter_action_opportunite','mettre_a_jour_opportunite') THEN SELECT * INTO a FROM affaires WHERE id=_affaire_id AND phase='opportunite' AND archived_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Opportunité non signée requise'; END IF; END IF; IF _tool='creer_opportunite' THEN result:=app_creer_opportunite_client(_p); ELSIF _tool='ajouter_action_opportunite' THEN result:=app_ajouter_action_opportunite(_affaire_id,(_p->>'type')::public.opp_action_type,_p->>'note',(_p->>'echeance')::date); ELSIF _tool='ajouter_note_chantier' THEN result:=app_ajouter_note_chantier(_affaire_id,_p->>'texte'); ELSIF _tool IN ('modifier_chantier','mettre_a_jour_opportunite') THEN patch:=_p->'patch'; allowed:=CASE WHEN _tool='modifier_chantier' THEN ARRAY['date_montage','date_demontage','lieu','contact_site_nom','contact_site_tel','chef_projet_id','charge_affaires_id','dessinateur_id','statut','montage_nb_techniciens','montage_travail_nuit','montage_nb_semi','montage_nb_20m3','montage_nature_prestation','montage_notes','notes'] ELSE ARRAY['nom','notes','lieu','date_montage','date_demontage','date_evenement_debut','date_evenement_fin','date_pat','typologie_future','ca_estime_ht','charge_affaires_id','statut_opportunite'] END; FOR k IN SELECT jsonb_object_keys(patch) LOOP IF NOT k=ANY(allowed) THEN RAISE EXCEPTION 'Champ interdit'; END IF; END LOOP; IF patch<>'{}'::jsonb THEN result:=app_modifier_affaire(_affaire_id,patch); ELSE result:=jsonb_build_object('id',_affaire_id); END IF; IF _tool='mettre_a_jour_opportunite' THEN IF _p->>'prochaine_action' IS NOT NULL THEN PERFORM app_ajouter_action_opportunite(_affaire_id,'note_interne',_p->>'prochaine_action',(_p->>'echeance')::date); END IF; IF _p->>'motif' IS NOT NULL THEN PERFORM app_ajouter_action_opportunite(_affaire_id,'note_interne',_p->>'motif',NULL); END IF; IF _p->>'jalon' IS NOT NULL THEN IF _p->>'jalon' NOT IN ('qualification','devis_envoye','negociation') THEN RAISE EXCEPTION 'Jalon signature interdit'; END IF; UPDATE opportunite_jalons SET date_prevue=(_p->>'echeance')::date WHERE affaire_id=_affaire_id AND etape::text=_p->>'jalon'; IF NOT FOUND THEN RAISE EXCEPTION 'Jalon absent: initialiser dans l’UI'; END IF; END IF; END IF; ELSIF _tool='creer_etape_logistique' THEN result:=app_creer_etape_logistique(_p-'cle_externe'); ELSIF _tool='modifier_etape_logistique' THEN patch:=_p->'patch'; IF patch ? 'statut' AND patch->>'statut' NOT IN ('propose','valide','fait') THEN RAISE EXCEPTION 'Annulation nécessite motif'; END IF; result:=app_modifier_etape_logistique(_etape_id,patch); ELSIF _tool='deplacer_etape_logistique' THEN result:=deplacer_etape_logistique(_etape_id,(_p->>'nouveau_debut')::date,(_p->>'nouvelle_fin')::date); ELSIF _tool='annuler_etape_logistique' THEN IF length(trim(_p->>'motif')) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Motif obligatoire'; END IF; result:=app_modifier_etape_logistique(_etape_id,jsonb_build_object('statut','annule','commentaire_equipe',_p->>'motif')); ELSE RAISE EXCEPTION 'Outil interdit'; END IF; RETURN result || jsonb_build_object('affaire_id',COALESCE(_affaire_id,(result->>'affaire_id')::uuid)); END $$;
ALTER FUNCTION public.mcp_dispatch_write(text,jsonb,uuid,uuid) OWNER TO mcp_business_rls;
REVOKE CREATE ON SCHEMA public FROM mcp_business_rls;
REVOKE ALL ON FUNCTION public.mcp_dispatch_write(text,jsonb,uuid,uuid) FROM PUBLIC,authenticated;
CREATE OR REPLACE FUNCTION public.mcp_execute_write_locked(_confirmation_id uuid,_tool text,_arguments_hash text,_payload jsonb,_diff jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.mcp_write_confirmations; cap text; result jsonb; kh text; a public.affaires; current_snapshot text; BEGIN BEGIN cap:=mcp_assert_write(_tool); SELECT * INTO c FROM mcp_write_confirmations WHERE id=_confirmation_id AND user_id=auth.uid() AND client_id=auth.jwt()->>'client_id' FOR UPDATE; IF NOT FOUND OR c.tool<>_tool OR c.arguments_hash<>_arguments_hash OR c.payload_hash<>encode(extensions.digest(_payload::text,'sha256'),'hex') THEN RAISE EXCEPTION 'Confirmation invalide ou arguments modifiés'; END IF; IF c.affaire_id IS NOT NULL THEN SELECT * INTO a FROM affaires WHERE id=c.affaire_id AND archived_at IS NULL FOR UPDATE; IF NOT FOUND OR NOT (user_cap_scope(cap)='all' OR (user_cap_scope(cap)='own' AND a.charge_affaires_id=auth.uid()) OR user_has_affaire_access(c.affaire_id)) THEN RAISE EXCEPTION 'Accès affaire refusé'; END IF; END IF; IF c.executed_at IS NOT NULL THEN RETURN c.result || jsonb_build_object('idempotent',true); END IF; IF c.expires_at<=now() THEN RAISE EXCEPTION 'Confirmation expirée'; END IF; IF c.etape_id IS NOT NULL THEN SELECT updated_at::text INTO current_snapshot FROM affaire_etapes_logistiques WHERE id=c.etape_id FOR UPDATE; ELSIF c.affaire_id IS NOT NULL THEN current_snapshot:=a.updated_at::text; END IF; IF c.snapshot IS NOT NULL AND c.snapshot::timestamptz IS DISTINCT FROM current_snapshot::timestamptz THEN RAISE EXCEPTION 'Données changées: demander un nouvel aperçu'; END IF; IF _payload->>'cle_externe' IS NOT NULL THEN kh:=encode(extensions.digest(_payload->>'cle_externe','sha256'),'hex'); PERFORM pg_advisory_xact_lock(hashtextextended(_tool||kh,0)); SELECT x.result INTO result FROM mcp_write_external_keys x WHERE x.tool=_tool AND key_hash=kh; IF result IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM mcp_write_external_keys x JOIN affaires aa ON aa.id=x.affaire_id WHERE x.tool=_tool AND key_hash=kh AND (user_cap_scope(cap)='all' OR user_has_affaire_access(aa.id))) THEN RAISE EXCEPTION 'Accès affaire refusé'; END IF; result:=result || jsonb_build_object('doublon_cle_externe',true); END IF; END IF; IF result IS NULL THEN result:=mcp_dispatch_write(_tool,_payload,c.affaire_id,c.etape_id); END IF; IF kh IS NOT NULL THEN INSERT INTO mcp_write_external_keys(tool,key_hash,affaire_id,etape_id,result) VALUES(_tool,kh,(result->>'affaire_id')::uuid,CASE WHEN _tool='creer_etape_logistique' THEN (result->>'id')::uuid END,result) ON CONFLICT DO NOTHING; END IF; UPDATE mcp_write_confirmations SET executed_at=now(),result=result WHERE id=c.id; INSERT INTO mcp_audit_log(user_id,client_id,tool,statut,confirmation_id,affaire_id,etape_id,diff,nb_lignes) VALUES(auth.uid(),auth.jwt()->>'client_id',_tool,'executed',c.id,COALESCE(c.affaire_id,(result->>'affaire_id')::uuid),COALESCE(c.etape_id,CASE WHEN _tool='creer_etape_logistique' THEN (result->>'id')::uuid END),mcp_safe_diff(_diff),1); RETURN result || jsonb_build_object('statut','executed'); EXCEPTION WHEN OTHERS THEN INSERT INTO mcp_audit_log(user_id,client_id,tool,statut,confirmation_id,affaire_id,etape_id) VALUES(auth.uid(),auth.jwt()->>'client_id',_tool,'refused',_confirmation_id,c.affaire_id,c.etape_id); RETURN jsonb_build_object('error',SQLERRM,'statut','refused'); END; END $$;
REVOKE ALL ON FUNCTION public.mcp_assert_write(text),public.mcp_write_preview(text,text,jsonb,uuid,uuid,text,jsonb),public.mcp_execute_write_locked(uuid,text,text,jsonb,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.mcp_assert_write(text),public.mcp_write_preview(text,text,jsonb,uuid,uuid,text,jsonb),public.mcp_execute_write_locked(uuid,text,text,jsonb,jsonb) TO authenticated;